    let table = Arc::new(Mutex::new(HashMap::new()));
    let handles: Vec<_> = (0..threads)
        .map(|_| {
            let table = Arc::clone(&table);
            thread::spawn(move || {
                for k in 0..keys {
                    get_or_compute(&table, k, || compute(k));
                }
            })
        })
        .collect();
    for h in handles {
        h.join().unwrap();
    }
    table
